"use client";

import * as React from "react";
import * as stylex from "@stylexjs/stylex";
import { vlak, mq } from "./tokens.stylex";
import { rs } from "./rs";

export interface SwitchProps
  extends Omit<React.ButtonHTMLAttributes<HTMLButtonElement>, "onChange"> {
  checked?: boolean;
  defaultChecked?: boolean;
  onCheckedChange?: (checked: boolean) => void;
}

const styles = stylex.create({
  track: {
    display: "inline-flex",
    boxSizing: "border-box",
    width: vlak.hit,
    height: vlak.hit,
    minWidth: vlak.hit,
    minHeight: vlak.hit,
    borderRadius: vlak.radiusSm,
    borderWidth: 0,
    position: "relative",
    flexShrink: 0,
    padding: 0,
    backgroundColor: "transparent",
    cursor: "pointer",
    // The visible rail is slim; the transparent button keeps a 44px hit area.
    "::before": {
      content: '""',
      boxSizing: "border-box",
      position: "absolute",
      top: "0.625rem",
      insetInlineStart: 0,
      width: "2.75rem",
      height: "1.5rem",
      borderRadius: "0.75rem",
      borderWidth: 1.5,
      borderStyle: "solid",
      borderColor: {
        default: vlak.controlBorder,
        [mq.forcedColors]: "ButtonText",
      },
      backgroundColor: "transparent",
      transition: {
        default: `background-color ${vlak.duration} ${vlak.ease}, border-color ${vlak.duration} ${vlak.ease}`,
        [mq.reduce]: "none",
      },
    },
    outlineWidth: {
      default: null,
      ":focus-visible": 2,
    },
    outlineStyle: {
      default: null,
      ":focus-visible": "solid",
    },
    outlineColor: {
      default: null,
      ":focus-visible": vlak.ink,
    },
    outlineOffset: {
      default: null,
      ":focus-visible": 2,
    },
  },
  on: {
    "::before": {
      backgroundColor: {
        default: vlak.ink,
        [mq.forcedColors]: "Highlight",
      },
      borderColor: {
        default: vlak.ink,
        [mq.forcedColors]: "Highlight",
      },
    },
    forcedColorAdjust: "none",
  },
  thumb: {
    position: "absolute",
    top: "0.84375rem",
    insetInlineStart: "0.21875rem",
    width: "1.0625rem",
    height: "1.0625rem",
    borderRadius: "50%",
    backgroundColor: {
      default: vlak.gray,
      [mq.forcedColors]: "ButtonText",
    },
    forcedColorAdjust: "none",
    transition: {
      default: `inset-inline-start ${vlak.duration} ${vlak.ease}`,
      [mq.reduce]: "none",
    },
  },
  thumbOn: {
    backgroundColor: {
      default: vlak.paper,
      [mq.forcedColors]: "HighlightText",
    },
    insetInlineStart: "1.46875rem",
  },
});

/** A button with role="switch". */
export const Switch = React.forwardRef<HTMLButtonElement, SwitchProps>(function Switch(
  { checked, defaultChecked, onCheckedChange, className, style, onClick, ...props },
  ref,
) {
  const [inner, setInner] = React.useState(defaultChecked ?? false);
  const isControlled = checked !== undefined;
  const on = isControlled ? checked : inner;
  const sx = rs(["rs-switch", on && "rs-switch-on", className], styles.track, on && styles.on);
  const knob = rs(["rs-switch-thumb", on && "rs-switch-thumb-on"], styles.thumb, on && styles.thumbOn);
  return (
    <button
      ref={ref}
      type="button"
      role="switch"
      aria-checked={on}
      className={sx.className}
      style={{ ...sx.style, ...style }}
      onClick={(e) => {
        if (!isControlled) setInner(!on);
        onCheckedChange?.(!on);
        onClick?.(e);
      }}
      {...props}
    >
      <i aria-hidden="true" className={knob.className} style={knob.style} />
    </button>
  );
});

/* ── switch: generated from packages/react/src/components/switch.tsx ── */
.rs-switch{display:inline-flex;box-sizing:border-box;width:var(--hit);height:var(--hit);min-width:var(--hit);min-height:var(--hit);border-radius:var(--radius-sm);border-width:0;position:relative;flex-shrink:0;padding:0;background-color:transparent;cursor:pointer}
.rs-switch::before{content:"";box-sizing:border-box;position:absolute;top:0.625rem;inset-inline-start:0;width:2.75rem;height:1.5rem;border-radius:0.75rem;border-width:1.5px;border-style:solid;border-color:var(--control-border);background-color:transparent;transition:background-color var(--duration) var(--ease), border-color var(--duration) var(--ease)}
.rs-switch:focus-visible{outline-width:2px;outline-style:solid;outline-color:var(--text);outline-offset:2px}
@media (forced-colors: active){.rs-switch::before{border-color:ButtonText}}
@media (prefers-reduced-motion: reduce){.rs-switch::before{transition:none}}
.rs-switch-on::before{background-color:var(--text);border-color:var(--text)}
.rs-switch-on{forced-color-adjust:none}
@media (forced-colors: active){.rs-switch-on::before{background-color:Highlight;border-color:Highlight}}
.rs-switch-thumb{position:absolute;top:0.84375rem;inset-inline-start:0.21875rem;width:1.0625rem;height:1.0625rem;border-radius:50%;background-color:var(--text-secondary);forced-color-adjust:none;transition:inset-inline-start var(--duration) var(--ease)}
@media (forced-colors: active){.rs-switch-thumb{background-color:ButtonText}}
@media (prefers-reduced-motion: reduce){.rs-switch-thumb{transition:none}}
.rs-switch-thumb-on{background-color:var(--bg);inset-inline-start:1.46875rem}
@media (forced-colors: active){.rs-switch-thumb-on{background-color:HighlightText}}

